// Subscribe once, for example in the form constructor
timer1.Tick += Timer1_Tick;

private void Timer1_Tick(object sender, EventArgs e)
{
    this.Text = DateTime.Now.ToLongTimeString();
}

// Subscribe once, for example in the form constructor
worker.DoWork += Worker_DoWork;

private void Worker_DoWork(object sender, DoWorkEventArgs e)
{
    for (int i = 1; i <= 100; i++)
    {
        if (worker.CancellationPending)
        {
            e.Cancel = true;
            return;
        }
        System.Threading.Thread.Sleep(20);
        worker.ReportProgress(i);
    }
}

// Subscribe once, for example in the form constructor
worker.ProgressChanged += Worker_ProgressChanged;

private void Worker_ProgressChanged(object sender, ProgressChangedEventArgs e)
{
    this.Text = e.ProgressPercentage + "%";
}

// Subscribe once, for example in the form constructor
worker.RunWorkerCompleted += Worker_RunWorkerCompleted;

private void Worker_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
{
    if (e.Cancelled)
    {
        MessageBox.Show("Cancelled.");
    }
    else if (e.Error != null)
    {
        MessageBox.Show(e.Error.Message);
    }
    else
    {
        MessageBox.Show("Done!");
    }
}

// Subscribe once, for example in the form constructor
notifyIcon1.MouseClick += NotifyIcon1_MouseClick;

private void NotifyIcon1_MouseClick(object sender, MouseEventArgs e)
{
    if (e.Button == MouseButtons.Left)
    {
        this.Show();
        this.WindowState = FormWindowState.Normal;
    }
}

// Subscribe once, for example in the form constructor
notifyIcon1.MouseDoubleClick += NotifyIcon1_MouseDoubleClick;

private void NotifyIcon1_MouseDoubleClick(object sender, MouseEventArgs e)
{
    this.Show();
    this.WindowState = FormWindowState.Normal;
}

// Subscribe once, for example in the form constructor
notifyIcon1.BalloonTipClicked += NotifyIcon1_BalloonTipClicked;

private void NotifyIcon1_BalloonTipClicked(object sender, EventArgs e)
{
    MessageBox.Show("You clicked the notification.");
}

// Subscribe once, for example in the form constructor
notifyIcon1.BalloonTipClosed += NotifyIcon1_BalloonTipClosed;

private void NotifyIcon1_BalloonTipClosed(object sender, EventArgs e)
{
    this.Text = "Notification closed";
}
